CREATE FUNCTION c1_api.receipt_ingest(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE r jsonb=q->'receipt';i c1_private.intents;t c1_private.dispatch_tickets;old c1_private.receipts;BEGIN PERFORM c1_private.guard(n);SELECT * INTO i FROM c1_private.intents WHERE ns=n AND id=(r->>'receipt_id')::uuid;SELECT * INTO t FROM c1_private.dispatch_tickets WHERE ns=n AND intent=i.id;IF NOT FOUND OR r->'operation' IS DISTINCT FROM (t.payload-'ticket_id'-'payload_hash'-'source_epoch'-'fencing_epoch'-'authorization_digest'-'store') OR NOT coalesce((r->>'final')::boolean,false) OR r->'scope' IS DISTINCT FROM (SELECT manifest->'stores'->(i.payload->>'store') FROM c1_private.deployment WHERE ns=n) THEN PERFORM c1_private.fail('RECEIPT_MISMATCH');END IF;SELECT * INTO old FROM c1_private.receipts WHERE ns=n AND id=r->>'receipt_id';IF FOUND THEN IF old.envelope IS DISTINCT FROM r THEN UPDATE c1_private.deployment SET halt=true,reason='FINAL_CONFLICT' WHERE ns=n;RETURN jsonb_build_object('error','FINAL_CONFLICT','status',503);END IF;RETURN jsonb_build_object('receipt_id',old.id,'noop',true);END IF;IF (SELECT count(*) FROM c1_private.receipts WHERE ns=n AND NOT applied)>=1000 THEN UPDATE c1_private.deployment SET halt=true,reason='BUFFER_LIMIT' WHERE ns=n;RETURN jsonb_build_object('error','BUFFER_LIMIT','status',503);END IF;INSERT INTO c1_private.receipts(ns,id,op,envelope,digest) VALUES(n,r->>'receipt_id',i.id,r,encode(sha256(convert_to(r::text,'UTF8')),'hex'));RETURN jsonb_build_object('receipt_id',r->>'receipt_id');END $$;
CREATE FUNCTION c1_api.receipt_list(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ BEGIN
 IF q ? 'receipt_id' THEN RETURN jsonb_build_object('receipt',(SELECT envelope FROM c1_private.receipts WHERE ns=n AND id=q->>'receipt_id'));END IF;
 IF coalesce((q->>'limit')::int,50) NOT BETWEEN 1 AND 50 THEN PERFORM c1_private.fail('PAGE_LIMIT');END IF;
 IF q ? 'snapshot' AND (q->>'snapshot')::bigint<>(SELECT height FROM c1_private.deployment WHERE ns=n) THEN PERFORM c1_private.fail('CURSOR_STALE');END IF;
 RETURN jsonb_build_object('receipts',(SELECT coalesce(jsonb_agg(jsonb_build_object('receipt_id',id,'height',height) ORDER BY height),'[]') FROM (SELECT id,(envelope->>'height')::bigint height FROM c1_private.receipts WHERE ns=n AND applied=coalesce((q->>'applied')::boolean,false) AND (envelope->>'height')::bigint>coalesce((q->>'after')::bigint,0) ORDER BY (envelope->>'height')::bigint LIMIT coalesce((q->>'limit')::int,50)) x));END $$;
CREATE FUNCTION c1_api.apply_receipt(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;r c1_private.receipts;i c1_private.intents;before_state jsonb;after_state jsonb;x jsonb;u c1_private.units;store_id text;meal_alias text;batch_intent c1_private.intents;v text;t c1_private.terms;v_totals jsonb;counts jsonb;f numeric=0;a numeric=0;rr numeric=0;h numeric=0;ss numeric=0;xx numeric=0;balance numeric;BEGIN
 d=c1_private.guard(n);SELECT * INTO r FROM c1_private.receipts WHERE ns=n AND id=q->>'receipt_id' FOR UPDATE;IF NOT FOUND THEN PERFORM c1_private.fail('NOT_FOUND');END IF;IF r.applied THEN RETURN jsonb_build_object('applied',true,'noop',true);END IF;SELECT * INTO i FROM c1_private.intents WHERE ns=n AND id=r.op;before_state=r.envelope->'transition'->'before';after_state=r.envelope->'transition'->'after';store_id=i.payload->>'store';
 IF (r.envelope->>'height')::bigint<>d.height+1 OR r.envelope->>'parent'<>d.parent OR (r.envelope->>'source_epoch')::bigint<>d.source_epoch OR (r.envelope->>'now')::bigint>d.now+2 THEN PERFORM c1_private.fail('SOURCE_GAP_OR_CLOCK');END IF;
 -- Independently compare all original immutable units and financial before state.
 IF jsonb_array_length(before_state->'units')<>(SELECT count(*) FROM c1_private.units WHERE ns=n AND store=store_id) THEN PERFORM c1_private.fail('UNIT_COUNT_MISMATCH');END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(before_state->'units') LOOP SELECT * INTO u FROM c1_private.units WHERE ns=n AND store=store_id AND seq=(x->>'seq')::int;IF NOT FOUND OR u.price::text<>x->>'price' OR u.bucket<>x->>'state' OR '0x'||encode(u.terms_hash,'hex')<>x->>'terms_hash' OR u.generation<>(x->>'generation')::numeric OR u.payer<>x->>'payer' OR u.version<>(x->>'version')::bigint OR u.voucher_id IS DISTINCT FROM x->>'voucher_id' THEN PERFORM c1_private.fail('ORIGINAL_UNIT_MISMATCH');END IF;END LOOP;
 IF i.action='fund' THEN INSERT INTO c1_private.orders VALUES(n,i.id,i.principal,i.payload->>'payer',store_id,i.payload->>'meal',(i.payload->>'version')::bigint,(i.payload->>'quantity')::int,c1_private.money(i.payload->'amount'));END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(after_state->'units') LOOP
 SELECT * INTO u FROM c1_private.units WHERE ns=n AND store=store_id AND seq=(x->>'seq')::int;
 IF NOT FOUND THEN IF i.action<>'fund' THEN PERFORM c1_private.fail('UNEXPECTED_NEW_UNIT');END IF;SELECT * INTO t FROM c1_private.terms WHERE ns=n AND store=store_id AND meal=i.payload->>'meal' AND version=(i.payload->>'version')::bigint;IF '0x'||encode(t.terms_hash,'hex')<>x->>'terms_hash' OR t.price::text<>x->>'price' OR x->>'payer'<>i.payload->>'payer' THEN PERFORM c1_private.fail('FUND_MISMATCH');END IF;INSERT INTO c1_private.units(ns,store,seq,order_id,local_index,payer,meal,version,terms_hash,price,bucket,generation) VALUES(n,store_id,(x->>'seq')::int,i.id,(x->>'local_index')::int,x->>'payer',t.meal,t.version,t.terms_hash,t.price,x->>'state',(x->>'generation')::numeric);
 ELSE IF u.price::text<>x->>'price' OR '0x'||encode(u.terms_hash,'hex')<>x->>'terms_hash' OR u.payer<>x->>'payer' OR u.version<>(x->>'version')::bigint THEN PERFORM c1_private.fail('IMMUTABLE_MISMATCH');END IF;
 -- Allowed bucket changes depend on original authority event/action, never arbitrary DTO.
 IF u.bucket<>x->>'state' AND NOT ((i.action='issue' AND ((u.bucket='A' AND x->>'state'='R') OR (u.bucket='R' AND x->>'state' IN('A','R') AND u.lock_id IS NULL AND u.marker_id IS NULL AND u.expires_at<=(r.envelope->>'now')::bigint))) OR (i.action='report' AND u.bucket='R' AND x->>'state'='H' AND u.marker_id IS NOT NULL) OR (i.action='settle' AND u.bucket='H' AND x->>'state'='S') OR (i.action='refund' AND u.bucket='A' AND x->>'state'='X') OR (i.action='expire' AND u.bucket='R' AND x->>'state'='A' AND u.lock_id IS NULL AND u.marker_id IS NULL AND u.expires_at<=(r.envelope->>'now')::bigint)) THEN PERFORM c1_private.fail('ILLEGAL_BUCKET_TRANSITION');END IF;
 UPDATE c1_private.units SET bucket=x->>'state',generation=(x->>'generation')::numeric,voucher_id=x->>'voucher_id',issued_at=(x->>'issued_at')::bigint,expires_at=(x->>'expires_at')::bigint,lock_id=x->'lock'->>'id',marker_id=x->'marker'->>'id',marker_at=(x->'marker'->>'at')::bigint,active_op=CASE WHEN active_op=i.id THEN NULL ELSE active_op END WHERE ns=n AND store=store_id AND seq=u.seq;
 END IF;END LOOP;
 IF i.action='issue' THEN v=r.envelope->'transition'->>'result';SELECT * INTO u FROM c1_private.units WHERE ns=n AND store=store_id AND voucher_id=v;IF NOT FOUND OR u.seq<>(i.payload->>'seq')::int OR u.generation<>(i.payload->>'generation')::numeric OR u.issued_at<>(r.envelope->>'now')::bigint OR u.expires_at<>u.issued_at+259200 THEN PERFORM c1_private.fail('ISSUE_MISMATCH');END IF;
 INSERT INTO c1_private.vouchers(ns,id,store,seq,generation,issue_op,email_key,original_subject,issued_at,expires_at) VALUES(n,v,store_id,u.seq,u.generation,i.id,c1_private.h(i.payload->>'issued_email_key'),i.principal,u.issued_at,u.expires_at);UPDATE c1_private.gates SET next_eligible=u.expires_at,pending=NULL WHERE ns=n AND kind='email' AND key=i.payload->>'issued_email_key' AND pending=i.id;
 END IF;
 IF i.action='publish' THEN SELECT * INTO t FROM c1_private.terms WHERE ns=n AND store=store_id AND meal=i.payload->>'meal' AND version=(i.payload->>'version')::bigint;IF NOT FOUND OR NOT c1_private.content_available(n,t.store,t.meal,t.version) OR '0x'||encode(t.terms_hash,'hex')<>r.envelope->'transition'->>'result' THEN PERFORM c1_private.fail('CONTENT_MISMATCH');END IF;INSERT INTO c1_private.catalog_head(ns,store,meal,version,listed) VALUES(n,store_id,t.meal,t.version,false) ON CONFLICT(ns,store,meal) DO UPDATE SET version=EXCLUDED.version;UPDATE c1_private.deployment SET catalog_revision=catalog_revision+1 WHERE ns=n;END IF;
 UPDATE c1_private.stores SET closed=(after_state->'controls'->>'closed')::boolean,paused=(after_state->'controls'->>'paused')::boolean,control_revision=(after_state->'controls'->>'revision')::bigint,lifetime=jsonb_array_length(after_state->'units') WHERE ns=n AND store=store_id;
 IF i.action='list' THEN UPDATE c1_private.catalog_head SET listed=(i.payload->>'listed')::boolean WHERE ns=n AND store=store_id AND meal=i.payload->>'meal';END IF;
 SELECT coalesce(sum(price),0),coalesce(sum(price) FILTER(WHERE bucket='A'),0),coalesce(sum(price) FILTER(WHERE bucket='R'),0),coalesce(sum(price) FILTER(WHERE bucket='H'),0),coalesce(sum(price) FILTER(WHERE bucket='S'),0),coalesce(sum(price) FILTER(WHERE bucket='X'),0),jsonb_build_object('F',count(*),'A',count(*) FILTER(WHERE bucket='A'),'R',count(*) FILTER(WHERE bucket='R'),'H',count(*) FILTER(WHERE bucket='H'),'S',count(*) FILTER(WHERE bucket='S'),'X',count(*) FILTER(WHERE bucket='X')) INTO f,a,rr,h,ss,xx,counts FROM c1_private.units WHERE ns=n AND store=store_id;
 balance=(after_state->'balances'->>(d.manifest->'stores'->store_id->>'escrow'))::numeric;IF f<>a+rr+h+ss+xx OR balance<a+rr+h OR f>115792089237316195423570985008687907853269984665640564039457584007913129639935 THEN PERFORM c1_private.fail('ACCOUNTING_MISMATCH');END IF;
 v_totals=jsonb_build_object('F',f::text,'A',a::text,'R',rr::text,'H',h::text,'S',ss::text,'X',xx::text,'liability',(a+rr+h)::text,'balance',balance::text,'counts',counts);UPDATE c1_private.rollups SET totals=v_totals WHERE ns=n AND store=store_id;
 UPDATE c1_private.gates SET pending=NULL WHERE ns=n AND pending=i.id;UPDATE c1_private.units SET active_op=NULL WHERE ns=n AND active_op=i.id;UPDATE c1_private.intents SET stage='FINAL_SUCCEEDED',result=jsonb_build_object('result',r.envelope->'transition'->'result','t0',r.envelope->'transition'->'t0','receipt',r.id) WHERE ns=n AND id=i.id;UPDATE c1_private.outbox SET state='DONE' WHERE ns=n AND intent=i.id;UPDATE c1_private.receipts SET applied=true WHERE ns=n AND id=r.id;INSERT INTO c1_private.financial_entries(ns,receipt,store,kind,amount,height) VALUES(n,r.id,store_id,i.action,CASE WHEN i.action='fund' THEN c1_private.money(i.payload->'amount') ELSE 0 END,(r.envelope->>'height')::bigint);
 PERFORM c1_private.failpoint(n,'apply_after_ledger');UPDATE c1_private.deployment SET height=(r.envelope->>'height')::bigint,parent=r.envelope->>'block_hash',heartbeat=now WHERE ns=n;RETURN jsonb_build_object('applied',true,'height',r.envelope->'height','totals',v_totals);END $$;
CREATE FUNCTION c1_api.observer_status(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ BEGIN IF coalesce((q->>'halt')::boolean,false) THEN PERFORM c1_private.guard(n);UPDATE c1_private.deployment SET halt=true,reason='INVALID_RECEIPT' WHERE ns=n;END IF;RETURN (SELECT jsonb_build_object('now',now,'height',height,'parent',parent,'source_epoch',source_epoch,'clock_floor',clock_floor,'halted',halt,'rebuilding',halt AND reason='CONTROLLED_RESTORE' AND EXISTS(SELECT 1 FROM c1_private.restore_runs WHERE ns=n AND state='INSTALLED'),'manifest',manifest) FROM c1_private.deployment WHERE ns=n);END $$;
